for i in range(1, 6):
    if i % 3 == 0:
        continue
    print(i, end=' ')

for i in range(3):
    for j in range(3):
        if i + j == 2:
            continue
        print(i, j, end=' ')

for i in range(2):
    for j in range(2):
        if i == j:
            continue
        print(i, j)
    else:
        print('inner done')
